d='d5510d61-54d2-4a55-885e-5b534b42fbab') OR EXISTS(SELECT 1 FROM combat_consumer_private.narrative_authorities WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c') OR (SELECT count(*) FROM public.combat_v2_sessions WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c')<>1 OR (SELECT count(*) FROM public.combat_v2_actors WHERE session_id='d5510d61-54d2-4a55-885e-5b534b42fbab')<>4 OR (SELECT count(*) FROM public.master_v2_nb_actor_offers_v1 WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c')<>2 OR NOT EXISTS(SELECT 1 FROM mission_creation_owner.human_actions WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c' AND request_key='06cdf2a6-cd64-4688-9d9c-94706510d920' AND actor_user='f0856d53-83a6-4de0-bc0c-12c87916e665' AND result->>'encounter_id'='d5510d61-54d2-4a55-885e-5b534b42fbab') THEN RAISE EXCEPTION 'HUMAN28_ACTUAL_ACTIVE_SCOPE_CAS_DRIFT';END IF; END IF;PERFORM mission_factory_owner.c444_runtime_ports_complete_assert_v1();END $post$;COMMIT;
